"use client";

/**
 * Product detail page — Limelight-style layout:
 * left thumbnail column + main image, right side details/cart actions.
 */
import { useState, useEffect } from "react";
import { useParams } from "next/navigation";
import { getProduct } from "@/lib/api";
import { useCart } from "@/lib/CartContext";

export default function ProductPage() {
  const { slug } = useParams<{ slug: string }>();
  const [product, setProduct] = useState<any>(null);
  const [qty, setQty] = useState(1);
  const [activeImage, setActiveImage] = useState<string | null>(null);
  const { addToCart } = useCart();

  useEffect(() => {
    getProduct(slug).then((data) => {
      setProduct(data);
      setActiveImage(data.image_url);
    });
  }, [slug]);

  if (!product) {
    return <div className="max-w-7xl mx-auto px-4 py-20 text-center text-neutral-400">Loading...</div>;
  }

  // Placeholder: repeat main image until backend supports multiple images per product
  const thumbnails = [product.image_url, product.image_url, product.image_url];

  return (
    <div className="max-w-7xl mx-auto px-4 py-10 bg-white text-neutral-900 grid md:grid-cols-[80px_1fr_400px] gap-6">
      {/* Thumbnail column */}
      <div className="flex md:flex-col gap-3 order-2 md:order-1">
        {thumbnails.map((thumb, i) => (
          <button
            key={i}
            onClick={() => setActiveImage(thumb)}
            className={`w-16 h-20 overflow-hidden border ${activeImage === thumb ? "border-neutral-900" : "border-neutral-200"}`}
          >
            <img src={thumb} alt={`${product.name} ${i + 1}`} className="w-full h-full object-cover" />
          </button>
        ))}
      </div>

      {/* Main image */}
      <div className="order-1 md:order-2 aspect-[3/4] bg-neutral-100 overflow-hidden">
        <img src={activeImage ?? product.image_url} alt={product.name} className="w-full h-full object-cover" />
      </div>

      {/* Details + cart action */}
      <div className="order-3">
        <h1 className="text-2xl font-semibold mb-2">{product.name}</h1>
        <p className="text-xl mb-6">Rs. {product.price}</p>

        <p className="text-sm font-medium mb-2">Quantity</p>
        <div className="flex items-center gap-3 mb-6">
          <button onClick={() => setQty((q) => Math.max(1, q - 1))} className="w-9 h-9 border rounded">-</button>
          <span className="w-6 text-center">{qty}</span>
          <button onClick={() => setQty((q) => q + 1)} className="w-9 h-9 border rounded">+</button>
        </div>

        <button
          onClick={() =>
            addToCart(
              { id: product.id, name: product.name, price: product.price, image_url: product.image_url },
              qty
            )
          }
          className="w-full bg-neutral-900 text-white rounded-lg py-3 font-medium tracking-wide mb-8"
        >
          ADD TO CART
        </button>

        <div className="border-t pt-4">
          <h3 className="font-semibold mb-2 underline underline-offset-4">Description</h3>
          <p className="text-sm text-neutral-600 mb-3">{product.description}</p>
          <p className="text-sm"><strong>Category:</strong> {product.category}</p>
          <p className="text-sm"><strong>In stock:</strong> {product.stock}</p>
        </div>
      </div>
    </div>
  );
}